per_step.command:
awk -F, '{
  gsub(/\r$/, "");
  if ($5 == "EXTERNAL" && ($4 + 0) < 10000) print $2
}' /app/data/transactions.log | sort | uniq -c | awk '$1 >= 5 {print $2}' > /tmp/struct_senders.txt
awk -F, '{
  gsub(/\r$/, "");
  if (NR == FNR) {
    suspicious[$1] = 1;
    next
  }
  if (NF < 5) next;
  amount = $4 + 0;
  type = $5;
  if (type == "INTERNAL") next;
  if (amount > 10000 || suspicious[$2]) print $0;
}' /tmp/struct_senders.txt /app/data/transactions.log | wc -l

cp /app/data/transactions.log /tmp/t.log
awk -F, '{
  gsub(/\r$/, "");
  if ($5 == "EXTERNAL" && ($4 + 0) < 10000) print $2
}' /tmp/t.log | sort | uniq -c | awk '$1 >= 5 {print $2}' > /tmp/struct_senders.txt
awk -F, '{
  gsub(/\r$/, "");
  if (NR == FNR) {
    suspicious[$1] = 1;
    next
  }
  if (NF < 5) next;
  amount = $4 + 0;
  type = $5;
  if (type == "INTERNAL") next;
  if (amount > 10000 || suspicious[$2]) print $0;
}' /tmp/struct_senders.txt /tmp/t.log | wc -l
